      "content": "{\n  \"name\": \"@xiaoyuyu6420/dsh-backup\",\n  \"version\": \"0.14.4\",\n  \"description\": \"一条命令备份、恢复与迁移 DeepSeek Harness（dsh）的全部数据（~/.dsh：会话、设置、插件、MCP、技能）：定时自动备份、升级前快照、换机迁移、会话日志体检修复、宿主起不来也能用的进程外救援；凭据默认脱敏只存本机。 Backup, restore & migrate all DeepSeek Harness (~/.dsh) data — sessions, settings, plugins, MCP, skills: scheduled backups, pre-upgrade snapshots, cross-machine migration, session-log doctor, out-of-process rescue console; credentials redacted to a local-only vault.\",\n  \"type\": \"module\",\n  \"packageManager\": \"pnpm@11.24.0\",\n  \"main\": \"lib/index.js\",\n  \"exports\": {\n    \".\": \"./lib/index.js\",\n    \"./client\": \"./lib/client.js\",\n    \"./cordis.patch.yml\": \"./cordis.patch.yml\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"lib\",\n    \"rescue\",\n    \"cordis.patch.yml\",\n    \"README.md\",\n    \"README.en.md\",\n    \"LICENSE\"\n  ],\n  \"bin\": {\n    \"dsh-rescue\": \"./rescue/rescue.mjs\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"platform\": \"web\",\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-runtime\",\n        \"@deepseek-ai/dsh-client-locale\",\n        \"@deepseek-ai/dsh-client-ui-settings\"\n      ]\n    }\n  },\n  \"keywords\": [\n    \"dsh\",\n    \"dsh-plugin\",\n    \"deepseek-harness\",\n    \"backup\",\n    \"备份\",\n    \"restore\",\n    \"恢复\",\n    \"migration\",\n    \"迁移\",\n    \"换机\",\n    \"schedule\",\n    \"自动备份\",\n    \"cross-platform\",\n    \"cross-machine\",\n    \"rescue\",\n    \"doctor\",\n    \"upgrade-snapshot\",\n    \"mcp\",\n    \"skills\",\n    \"技能\",\n    \"sessions\",\n    \"会话\",\n    \"workspace\",\n    \"工作区\",\n    \"vault\",\n    \"数据安全\"\n  ],\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.1\",\n    \"@deepseek-ai/dsh-commands\": \"^0.1.1-rc.2 || ^0.1.2-rc.1 || ^0.1.5-rc.1 || ^0.1.6-alpha.1 || ^0.1.7-alpha.1 || ^0.2.0-rc.1\",\n    \"@deepseek-ai/dsh-fs\": \"^0.1.1-rc.2 || ^0.1.2-rc.1 || ^0.1.5-rc.1 || ^0.1.6-alpha.1 || ^0.1.7-alpha.1 || ^0.2.0-rc.1\",\n    \"@deepseek-ai/dsh-settings\": \"^0.1.1-rc.2 || ^0.1.2-rc.1 || ^0.1.5-rc.1 || ^0.1.6-alpha.1 || ^0.1.7-alpha.1 || ^0.2.0-rc.1\",\n    \"@deepseek-ai/dsh-subprocess\": \"^0.1.1-rc.2 || ^0.1.2-rc.1 || ^0.1.5-rc.1 || ^0.1.6-alpha.1 || ^0.1.7-alpha.1 || ^0.2.0-rc.1\",\n    \"@deepseek-ai/dsh-tools\": \"^0.1.1-rc.2 || ^0.1.2-rc.1 || ^0.1.5-rc.1 || ^0.1.6-alpha.1 || ^0.1.7-alpha.1 || ^0.2.0-rc.1\",\n    \"@deepseek-ai/dsh-typert-protocol\": \"^0.1.1-rc.2 || ^0.1.2-rc.1 || ^0.1.5-rc.1 || ^0.1.6-alpha.1 || ^0.1.7-alpha.1 || ^0.2.0-rc.1\",\n    \"@deepseek-ai/schemastery\": \"^3.18.1\"\n  },\n  \"devDependencies\": {\n    \"esbuild\": \"^0.25.0\",\n    \"react\": \"^19.0.0\",\n    \"react-dom\": \"^19.0.0\",\n    \"zod\": \"^4.4.3\"\n  },\n  \"engines\": {\n    \"node\": \">=20\",\n    \"dsh\": \"^0.1.1-rc.2 || ^0.1.2-rc.1 || ^0.1.5-rc.1 || ^0.1.6-alpha.1 || ^0.1.7-alpha.1 || ^0.2.0-rc.1\"\n  },\n  \"license\": \"MIT\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/xiaoyuyu6420/dsh-backup.git\"\n  },\n  \"homepage\": \"https://github.com/xiaoyuyu6420/dsh-backup#readme\",\n  \"bugs\": {\n    \"url\": \"https://github.com/xiaoyuyu6420/dsh-backup/issues\"\n  },\n  \"publishConfig\": {\n    \"access\": \"public\"\n  }\n}\n"
